import{_ as a,o as t,c as i,a3 as n}from"./chunks/framework.Dz5Q8p4s.js";const p=JSON.parse('{"title":"Autoregressive Video Generation","description":"","frontmatter":{"title":"Autoregressive Video Generation","outline":[2,2]},"headers":[],"relativePath":"en/tutorials/autoregressive.md","filePath":"en/tutorials/autoregressive.md","lastUpdated":null}'),r={name:"en/tutorials/autoregressive.md"};function o(l,e,s,h,c,d){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="autoregressive-video-generation" tabindex="-1">Autoregressive Video Generation <a class="header-anchor" href="#autoregressive-video-generation" aria-label="Permalink to &quot;Autoregressive Video Generation&quot;">​</a></h1><blockquote><p><strong>Full text (Chinese)</strong>: <a href="/notes/tutorials/autoregressive">自回归视频生成</a><strong>Coverage</strong>: June 2025 – July 2026, tracing back to Diffusion Forcing, CausVid, MAGI-1 and Self-Forcing. <strong>Papers</strong>: <a href="/notes/en/papers/#tut-autoregressive">90 deep-read notes</a></p></blockquote><div class="warning custom-block"><p class="custom-block-title">About this English page</p><p>The tutorial itself is written in Chinese. This page is its English companion: it gives the complete chapter-by-chapter structure and states what each chapter argues. Every derivation, table, diagram and per-paper breakdown lives in the <a href="/notes/tutorials/autoregressive">Chinese edition</a>; the <a href="/notes/en/papers/">paper library</a> is fully browsable in English.</p></div><h2 id="what-this-tutorial-is-about" tabindex="-1">What this tutorial is about <a class="header-anchor" href="#what-this-tutorial-is-about" aria-label="Permalink to &quot;What this tutorial is about&quot;">​</a></h2><p>A bidirectional video diffusion model must decide the whole clip at once. An autoregressive one commits to a prefix and extends it, which buys four things — unbounded length, streaming output, interactive control, and a natural place to inject actions — and costs one thing that dominates the entire literature: <strong>exposure bias and the error accumulation it causes</strong>.</p><p>The tutorial separates three schools (discrete-token next-token prediction, continuous-token AR without quantisation, and autoregressive diffusion / Diffusion Forcing), then argues that the decisive design choices are not the school but (a) the temporal unit, chunk-wise versus frame-wise, (b) teacher forcing versus self-forcing during training, and (c) how the KV cache is managed once the video runs past the training horizon. Chapter 5 dissects representative systems one at a time; Chapter 8 is the grouped index.</p><h2 id="chapter-outline" tabindex="-1">Chapter outline <a class="header-anchor" href="#chapter-outline" aria-label="Permalink to &quot;Chapter outline&quot;">​</a></h2><h3 id="chapter-0-—-how-to-use-this-tutorial" tabindex="-1">Chapter 0 — How to use this tutorial <a class="header-anchor" href="#chapter-0-—-how-to-use-this-tutorial" aria-label="Permalink to &quot;Chapter 0 — How to use this tutorial&quot;">​</a></h3><ul><li>0.1 What we are covering</li><li>0.2 Suggested reading paths</li><li>0.3 Scope</li></ul><h3 id="chapter-1-—-concepts-and-intuition" tabindex="-1">Chapter 1 — Concepts and intuition <a class="header-anchor" href="#chapter-1-—-concepts-and-intuition" aria-label="Permalink to &quot;Chapter 1 — Concepts and intuition&quot;">​</a></h3><ul><li>1.1 What &quot;autoregressive video generation&quot; means</li><li>1.2 Why go autoregressive — four motivations</li><li>1.3 The three technical schools</li><li>1.4 Key terminology at a glance</li><li>1.5 Relation to adjacent fields</li></ul><h3 id="chapter-2-—-mathematical-principles-and-key-techniques" tabindex="-1">Chapter 2 — Mathematical principles and key techniques <a class="header-anchor" href="#chapter-2-—-mathematical-principles-and-key-techniques" aria-label="Permalink to &quot;Chapter 2 — Mathematical principles and key techniques&quot;">​</a></h3><p>The theoretical spine. Section 2.6 on exposure bias is described as the Achilles&#39; heel of the whole area.</p><ul><li>2.1 Autoregressive factorisation and causality</li><li>2.2 School 1: next-token prediction over discrete tokens</li><li>2.3 School 2: continuous-token AR without quantisation</li><li>2.4 School 3: autoregressive diffusion and Diffusion Forcing (key section)</li><li>2.5 Chunk-wise vs frame-wise: choosing the temporal unit</li><li>2.6 Teacher forcing vs self-forcing: exposure bias</li><li>2.7 Causal attention and the KV cache: the engine and the bottleneck</li><li>2.8 Causal VAEs and video tokenizers</li><li>2.9 Few-step distillation and real-time inference</li><li>2.10 Error accumulation and drift: why long videos collapse</li></ul><h3 id="chapter-3-—-task-taxonomy" tabindex="-1">Chapter 3 — Task taxonomy <a class="header-anchor" href="#chapter-3-—-task-taxonomy" aria-label="Permalink to &quot;Chapter 3 — Task taxonomy&quot;">​</a></h3><ul><li>3.1 Panorama of tasks</li><li>3.2 Basic generation: T2V / I2V / V2V</li><li>3.3 Long video and extrapolation</li><li>3.4 Streaming and real-time</li><li>3.5 Multi-shot narrative</li><li>3.6 Action-conditioned world models</li><li>3.7 Exploration and camera control</li><li>3.8 Multi-entity control and language-as-action</li><li>3.9 Embodiment and physics: robotics and driving</li><li>3.10 Vertical applications</li><li>3.11 A &quot;task → representative work → metric to watch&quot; table</li></ul><h3 id="chapter-4-—-data" tabindex="-1">Chapter 4 — Data <a class="header-anchor" href="#chapter-4-—-data" aria-label="Permalink to &quot;Chapter 4 — Data&quot;">​</a></h3><ul><li>4.1 Why data matters especially for AR</li><li>4.2 Layer 1: tokenizer / VAE training data</li><li>4.3 Layer 2: pretraining data (large-scale video–text)</li><li>4.4 Layer 3: long-video and extrapolation data</li><li>4.5 Layer 4: task-specific data</li><li>4.6 Synthetic and self-distilled data — AR&#39;s distinctive weapon</li></ul><h3 id="chapter-5-—-methods-and-representative-systems-core-chapter" tabindex="-1">Chapter 5 — Methods and representative systems (core chapter) <a class="header-anchor" href="#chapter-5-—-methods-and-representative-systems-core-chapter" aria-label="Permalink to &quot;Chapter 5 — Methods and representative systems (core chapter)&quot;">​</a></h3><p>Every paper cited in the tutorial is broken down here as problem → core idea → mechanism → result.</p><ul><li>5.1 Backbone paradigms: laying the foundation for AR video</li><li>5.2 Long video and extrapolation: surviving past the minute mark</li><li>5.3 Memory and KV-cache management: the most contested battleground of 2026</li><li>5.4 Acceleration, distillation and quantisation: pushing AR to real time</li><li>5.5 Training-free sampling and stability: fixes that touch only inference</li><li>5.6 Control and interactive world models</li><li>5.7 Reinforcement learning and reward alignment</li><li>5.8 Bidirectional / any-order AR: breaking the forward-only constraint</li><li>5.9 Embodiment and physics: AR video as simulator and as policy</li><li>5.10 Vertical applications</li></ul><h3 id="chapter-6-—-benchmarks-and-evaluation" tabindex="-1">Chapter 6 — Benchmarks and evaluation <a class="header-anchor" href="#chapter-6-—-benchmarks-and-evaluation" aria-label="Permalink to &quot;Chapter 6 — Benchmarks and evaluation&quot;">​</a></h3><ul><li>6.1 Three dimensions of evaluation</li><li>6.2 General video-quality benchmarks</li><li>6.3 Long-horizon / world-model / narrative benchmarks</li><li>6.4 Physical-consistency benchmarks</li><li>6.5 Embodied and driving benchmarks</li><li>6.6 Efficiency and real-time metrics</li><li>6.7 How evaluation should be done in practice</li></ul><h3 id="chapter-7-—-core-challenges-and-research-trends" tabindex="-1">Chapter 7 — Core challenges and research trends <a class="header-anchor" href="#chapter-7-—-core-challenges-and-research-trends" aria-label="Permalink to &quot;Chapter 7 — Core challenges and research trends&quot;">​</a></h3><ul><li>7.1 Error accumulation and drift — still problem number one</li><li>7.2 Long-term memory: fixed budget vs unbounded history</li><li>7.3 The tension between real-time operation and scale</li><li>7.4 Physical consistency and &quot;true&quot; world models</li><li>7.5 Evaluation methodology</li><li>7.6 Controllability and interaction interfaces</li><li>7.7 Three overarching trends</li></ul><h3 id="chapter-8-—-paper-list-2025-06–2026-07" tabindex="-1">Chapter 8 — Paper list (2025.06–2026.07) <a class="header-anchor" href="#chapter-8-—-paper-list-2025-06–2026-07" aria-label="Permalink to &quot;Chapter 8 — Paper list (2025.06–2026.07)&quot;">​</a></h3><p>Foundational work; backbone paradigms and new architectures; long video and extrapolation; memory and KV-cache management; acceleration, distillation and quantisation; training-free sampling and stability; control and interactive world models; RL and reward alignment; bidirectional/any-order AR; embodiment and physics; vertical applications.</p><h3 id="appendices" tabindex="-1">Appendices <a class="header-anchor" href="#appendices" aria-label="Permalink to &quot;Appendices&quot;">​</a></h3><ul><li>Appendix A — Glossary</li><li>Appendix B — Suggested learning path</li></ul><h2 id="related-tutorials" tabindex="-1">Related tutorials <a class="header-anchor" href="#related-tutorials" aria-label="Permalink to &quot;Related tutorials&quot;">​</a></h2><ul><li><a href="/notes/en/tutorials/acceleration-distillation">Acceleration &amp; Distillation</a> — few-step and streaming distillation in depth</li><li><a href="/notes/en/tutorials/world-models">World Models</a> — where action conditioning enters the autoregressive loop</li><li><a href="/notes/en/tutorials/video-to-wam">From Video Generation to WAM</a> — what changes when the same causal machinery has to serve control</li></ul>',31)])])}const m=a(r,[["render",o]]);export{p as __pageData,m as default};
